B.aqM=new A.P("Lu\u1eadt","\u0110i\u1ec1n s\u1ed1 1\u20139 sao cho m\u1ed7i h\xe0ng, m\u1ed7i c\u1ed9t v\xe0 m\u1ed7i kh\u1ed1i 3\xd73 ch\u1ee9a \u0111\u1ee7 1\u20139 kh\xf4ng l\u1eb7p l\u1ea1i.")
B.apR=new A.P("\u0110\u1ed9 kh\xf3",'M\u1ed7i \u0111\u1ec1 c\xf3 \u0111\xfang m\u1ed9t l\u1eddi gi\u1ea3i. \u0110\u1ed9 kh\xf3 \u0111\u01b0\u1ee3c ch\u1ea5m b\u1eb1ng k\u1ef9 thu\u1eadt c\u1ea7n d\xf9ng: D\u1ec5 = ch\u1ec9 c\u1ea7n "\xf4 duy nh\u1ea5t"; Trung b\xecnh = c\u1ea7n "v\u1ecb tr\xed duy nh\u1ea5t"; Kh\xf3 = c\u1ea7n lo\u1ea1i tr\u1eeb c\u1eb7p/kh\xf3a ho\u1eb7c th\u1eed-sai.')
B.aqU=new A.P("Ghi ch\xfa",'B\u1eadt ch\u1ebf \u0111\u1ed9 "Ghi ch\xfa" \u0111\u1ec3 \u0111i\u1ec1n s\u1ed1 nh\u1ecf l\xe0m nh\xe1p. Khi \u0111i\u1ec1n s\u1ed1 ch\xednh, c\xe1c ghi ch\xfa tr\xf9ng trong c\xf9ng h\xe0ng/c\u1ed9t/kh\u1ed1i t\u1ef1 xo\xe1.')
B.aqg=new A.P("\u0110i\u1ec3m","\u0110i\u1ec3m c\u01a1 b\u1ea3n D\u1ec5 1000 / Trung b\xecnh 2000 / Kh\xf3 3500, tr\u1eeb 2 \u0111i\u1ec3m m\u1ed7i gi\xe2y, 50 \u0111i\u1ec3m m\u1ed7i l\u1ed7i, 100 \u0111i\u1ec3m m\u1ed7i g\u1ee3i \xfd (t\u1ed1i thi\u1ec3u 100).")
B.afu=s([B.aqM,B.apR,B.aqU,B.aqg],t.Wy)
B.aqk=new A.P("Lu\u1eadt","K\xe9o c\xe1c m\u1ea3nh \u1edf khay d\u01b0\u1edbi v\xe0o khung tranh. M\u1ea3nh th\u1ea3 g\u1ea7n \u0111\xfang v\u1ecb tr\xed s\u1ebd t\u1ef1 h\xfat v\xe0o.")
B.apQ=new A.P("C\u1ea5p \u0111\u1ed9","3\xd73 (9 m\u1ea3nh) \u0111\u1ebfn 6\xd76 (36 m\u1ea3nh). C\xf3 th\u1ec3 xem \u1ea3nh m\u1eabu b\u1ea5t k\u1ef3 l\xfac n\xe0o.")
B.aqV=new A.P("\u0110i\u1ec3m","500 + 30\xd7s\u1ed1 m\u1ea3nh, tr\u1eeb 1 \u0111i\u1ec3m m\u1ed7i gi\xe2y, 5 \u0111i\u1ec3m m\u1ed7i l\u1ea7n th\u1ea3 sai, 50 \u0111i\u1ec3m m\u1ed7i g\u1ee3i \xfd (t\u1ed1i thi\u1ec3u 50).")
B.aaP=s([B.aqk,B.apQ,B.aqV],t.Wy)
B.arn=new A.P("Lu\u1eadt","B\xe0n 15\xd715. Ai c\xf3 5 qu\xe2n li\xean ti\u1ebfp (ngang, d\u1ecdc ho\u1eb7c ch\xe9o) tr\u01b0\u1edbc th\xec th\u1eafng. H\u1ebft ch\u1ed7 m\xe0 kh\xf4ng ai th\u1eafng th\xec ho\xe0. X lu\xf4n \u0111i tr\u01b0\u1edbc.")
B.arf=new A.P("Qu\xe2n X/O","M\u1ed7i v\xe1n m\u1edbi, h\u1ec7 th\u1ed1ng b\u1ed1c ng\u1eabu nhi\xean cho b\u1ea1n qu\xe2n X ho\u1eb7c O. X lu\xf4n \u0111i tr\u01b0\u1edbc: n\u1ebfu b\u1ea1n l\xe0 O th\xec m\xe1y \u0111i tr\u01b0\u1edbc. V\xe1n ti\u1ebfp t\u1ee5c t\u1eeb b\u1ea3n l\u01b0u gi\u1eef nguy\xean qu\xe2n v\xe0 l\u01b0\u1ee3t.")
B.aqu=new A.P("\u0110\u1ed9 kh\xf3","D\u1ec5: ph\xf9 h\u1ee3p cho ng\u01b0\u1eddi m\u1edbi b\u1eaft \u0111\u1ea7u, m\xe1y ch\u01a1i \u0111\u01a1n gi\u1ea3n v\xe0 \u0111\xf4i khi m\u1eafc l\u1ed7i. V\u1eeba: m\xe1y bi\u1ebft ph\xf2ng th\u1ee7 v\xe0 t\xecm c\u01a1 h\u1ed9i chi\u1ebfn th\u1eafng. Kh\xf3: m\xe1y t\xednh to\xe1n c\u1ea9n th\u1eadn h\u01a1n v\xe0 \u0111\u01b0a ra nh\u1eefng n\u01b0\u1edbc \u0111i kh\xf3 \u0111\u1ed1i ph\xf3.")
B.ark=new A.P("Sai l\u1ea7m l\u1edbn","\u0110\u01b0\u1ee3c t\xednh khi b\u1ea1n b\u1ecf l\u1ee1 n\u01b0\u1edbc th\u1eafng ngay, ho\u1eb7c kh\xf4ng ch\u1eb7n n\u01b0\u1edbc th\u1eafng ngay c\u1ee7a \u0111\u1ed1i th\u1ee7 trong khi v\u1eabn c\xf2n ch\u1eb7n \u0111\u01b0\u1ee3c. N\u1ebfu \u0111\u1ed1i th\u1ee7 \u0111\xe3 c\xf3 hai \u0111\u1ea7u th\u1eafng (kh\xf4ng th\u1ec3 c\u1ee9u) th\xec kh\xf4ng t\xednh.")
B.aqR=new A.P("\u0110i\u1ec3m","Th\u1eafng: D\u1ec5 300 / V\u1eeba 600 / Kh\xf3 1000 + th\u01b0\u1edfng th\u1eafng nhanh max(0, 300 \u2212 3\xd7s\u1ed1 n\u01b0\u1edbc), tr\u1eeb 100 m\u1ed7i g\u1ee3i \xfd. Ho\xe0: 1/3 \u0111i\u1ec3m c\u01a1 b\u1ea3n. Thua: 0.")
B.abc=s([B.arn,B.arf,B.aqu,B.ark,B.aqR],t.Wy)
B.aq6=new A.P("Rubik \u2014 tr\u1ee3 l\xfd gi\u1ea3i",'Thu\u1eadt to\xe1n Two-Phase (Kociemba) ch\u1ea1y offline trong lu\u1ed3ng n\u1ec1n; l\u1eddi gi\u1ea3i \u0111\u01b0\u1ee3c \xe1p th\u1eed l\xean kh\u1ed1i tr\u01b0\u1edbc khi d\xf9ng. L\u1eddi gi\u1ea3i th\u01b0\u1eddng \u2264 22 n\u01b0\u1edbc nh\u01b0ng kh\xf4ng \u0111\u1ea3m b\u1ea3o ng\u1eafn nh\u1ea5t. "T\u1ed1i \u01b0u s\u1ed1 n\u01b0\u1edbc" ch\u1ec9 t\xecm l\u1eddi gi\u1ea3i ng\u1eafn h\u01a1n trong th\u1eddi gian cho ph\xe9p.')
B.aqw=new A.P("Rubik \u2014 c\xe1ch \u0111\u1ebfm l\u01b0\u1ee3t",'"S\u1ed1 l\u01b0\u1ee3t xoay" l\xe0 th\u01b0\u1edbc \u0111o HTM: m\u1ed7i l\u1ea7n xoay m\u1ed9t m\u1eb7t 90\xb0 ho\u1eb7c 180\xb0 t\xednh 1. Th\u01b0\u1edbc \u0111o QTM t\xednh xoay 180\xb0 l\xe0 2. S\u1ed1 Th\u1ea7n: m\u1ecdi tr\u1ea1ng th\xe1i gi\u1ea3i \u0111\u01b0\u1ee3c trong \u2264 20 HTM (\u2264 26 QTM).')
B.ar4=new A.P("Caro \u2014 m\xe1y ch\u01a1i th\u1ebf n\xe0o","D\u1ec5: \u0111\xe1nh gi\xe1 nhanh t\u1eebng \xf4 c\xf3 y\u1ebfu t\u1ed1 ng\u1eabu nhi\xean, kh\xf4ng t\xednh tr\u01b0\u1edbc. V\u1eeba: lu\xf4n th\u1eafng ngay/ch\u1eb7n n\u01b0\u1edbc b\u1ed1n, minimax 2 l\u1edbp tr\xean 10 \u1ee9ng vi\xean t\u1ed1t nh\u1ea5t. Kh\xf3: minimax alpha\u2013beta \u0111\xe0o s\xe2u d\u1ea7n t\u1edbi 8 l\u1edbp, s\u1eafp x\u1ebfp n\u01b0\u1edbc theo heuristic, gi\u1edbi h\u1ea1n 1,5 gi\xe2y m\u1ed7i n\u01b0\u1edbc. T\u1ea5t c\u1ea3 ch\u1ea1y offline trong lu\u1ed3ng n\u1ec1n.")
B.aqq=new A.P("Sudoku \u2014 ch\u1ea5m \u0111\u1ed9 kh\xf3","M\u1ed7i \u0111\u1ec1 c\xf3 \u0111\xfang m\u1ed9t l\u1eddi gi\u1ea3i; \u0111\u1ed9 kh\xf3 ch\u1ea5m theo k\u1ef9 thu\u1eadt c\u1ea7n d\xf9ng (\xf4 duy nh\u1ea5t, v\u1ecb tr\xed duy nh\u1ea5t, lo\u1ea1i tr\u1eeb c\u1eb7p/kho\xe1 ho\u1eb7c th\u1eed-sai).")
B.adP=s([B.aq6,B.aqw,B.ar4,B.aqq],t.Wy)
B.aqs=new A.P("T\xe0i kho\u1ea3n","Kh\xf4ng b\u1eaft bu\u1ed9c. Ch\u1ebf \u0111\u1ed9 kh\xe1ch ch\u01a1i \u0111\u1ea7y \u0111\u1ee7 offline. Khi \u0111\u0103ng nh\u1eadp, k\u1ebft qu\u1ea3 \u0111\u01b0\u1ee3c \u0111\u1ed3ng b\u1ed9; n\u1ebfu m\u1ea5t m\u1ea1ng, k\u1ebft qu\u1ea3 \u0111\u01b0\u1ee3c gi\u1eef tr\xean m\xe1y v\xe0 g\u1eedi l\u1ea1i sau.")
B.aqQ=new A.P("Ch\u1ed1ng gian l\u1eadn","Server t\u1ef1 t\xednh l\u1ea1i \u0111i\u1ec3m v\xe0 ki\u1ec3m tra t\xednh h\u1ee3p l\u1ec7 (v\xed d\u1ee5: l\u1eddi gi\u1ea3i Rubik ph\u1ea3i th\u1ef1c s\u1ef1 gi\u1ea3i \u0111\u01b0\u1ee3c x\xe1o tr\u1ed9n).")
B.arq=new A.P("Th\xe1ch \u0111\u1ea5u","Hai ng\u01b0\u1eddi gi\u1ea3i c\xf9ng m\u1ed9t x\xe1o tr\u1ed9n Rubik. L\u1eddi gi\u1ea3i t\u1ef1 l\u1ef1c lu\xf4n x\u1ebfp tr\xean l\u1eddi gi\u1ea3i c\xf3 tr\u1ee3 gi\xfap; c\xf9ng lo\u1ea1i th\xec ai nhanh h\u01a1n th\u1eafng.")
B.aqS=new A.P("G\u1ea7n \u0111\xe2y","Ch\u1ec9 ho\u1ea1t \u0111\u1ed9ng khi b\u1ea1n b\u1eadt. \u1ee8ng d\u1ee5ng l\u1ea5y v\u1ecb tr\xed g\u1ea7n \u0111\xfang (~1 km) m\u1ed9t l\u1ea7n khi b\u1ea1n m\u1edf m\xe0n h\xecnh, kh\xf4ng theo d\xf5i li\xean t\u1ee5c. Ng\u01b0\u1eddi kh\xe1c ch\u1ec9 th\u1ea5y kho\u1ea3ng c\xe1ch \u01b0\u1edbc l\u01b0\u1ee3ng, kh\xf4ng th\u1ea5y to\u1ea1 \u0111\u1ed9.")
